  "claims": [
    {
      "card_ids": ["C38"],
      "claim": "Tetrabenazine, a close structural analog sharing the dimethoxy-tetrahydroisoquinoline core, has very low oral systemic availability (mean 0.049 ± 0.032) in patients.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Valbenazine, a related VMAT2 inhibitor with a dimethoxy-tetrahydroisoquinoline core, has an absolute oral bioavailability of approximately 49% in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Noscapine, a dimethoxy-substituted isoquinoline alkaloid, has an absolute oral bioavailability of about 30% in humans, with wide interindividual variation.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C62"],
      "claim": "Almorexant, a structurally distinct but lipophilic CNS drug, has low absolute oral bioavailability of about 11%, indicating that extensive first-pass metabolism can dominate in this chemical space.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query molecule is a dimethoxy-substituted tetrahydroisoquinoline lactam with a basic amine side chain, closely related to tetrabenazine and valbenazine. Direct analog evidence shows very low (tetrabenazine ~5%) to moderate (valbenazine ~49%) oral bioavailability, with no evidence supporting high (≥20%) bioavailability. The balance of transferable experimental evidence favors F < 20%.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement exists for the exact query molecule.",
    "The query's lactam and tertiary amine side chain may alter first-pass metabolism relative to tetrabenazine or valbenazine, but the direction of any change is uncertain.",
    "No human pharmacokinetic data for the query molecule itself are available."
  ],
